"""Compare identical assignment objectives with old versus tighter bounds."""
import copy, hashlib, importlib.util, json, sys, time
from pathlib import Path
from types import SimpleNamespace
import numpy as np
def module(version):
    path=Path('/tmp/p3b5_'+version+'_offline_draft/control.py')
    spec=importlib.util.spec_from_file_location('multi_robot_exploration.compare_'+version,path)
    obj=importlib.util.module_from_spec(spec);sys.modules[spec.name]=obj;spec.loader.exec_module(obj)
    return obj
old,new=module('v45'),module('v47')
sources=[Path('log/p3b5/p3b5_v40_fixed_ap/p3b5_v40_fixed_lab_lab_far_northwest_3r_seed202_ap/snapshots.jsonl'),
         Path('log/p3b5_development/p3b5_v44_isolated_development_lab202/ap/snapshots.jsonl')]
output={'scope':'Conditional received AP geometry plus explicitly synthetic battery/mode variations. No original internal buffer replay, new mission, control input, truth or formal qualification.',
    'source':Path(__file__).read_text(),'control_sha256':{v:hashlib.sha256(Path(c.__file__).read_bytes()).hexdigest()
        for v,c in [('v45',old),('v47',new)]},'snapshot_sha256':{},'cases':[]}
def namespace(value):
    return SimpleNamespace(**{k:namespace(v) if isinstance(v,dict) else v for k,v in value.items()})
for source in sources:
    output['snapshot_sha256'][str(source)]=hashlib.sha256(source.read_bytes()).hexdigest()
    row=json.loads(next(source.open()));messages=row['messages'];info=messages['map']['info']
    grid=np.asarray(messages['map']['data']).reshape(info['height'],info['width'])
    origin=tuple(info['origin']['position'][k] for k in ('x','y'))
    received_states={n:json.loads(messages[n+'/battery_state']['data']) for n in ('tb1','tb2','tb3')}
    positions={}
    for n in received_states:
        odom=messages[n+'/odom']['pose']['pose']['position']
        tf=next(t['transform'] for t in messages[n+'/tf']['transforms']
                if t['header']['frame_id'].endswith('map') and t['child_frame_id'].endswith('odom'))
        positions[n]=old.transform_point_2d(odom['x'],odom['y'],namespace(tf))
    detection=json.loads(messages['target_detection']['data']);target=(detection['target_x'],detection['target_y'])
    for observer in positions:
        for variant in ('received','energy90percent','charging_tb2'):
            states=copy.deepcopy(received_states);planning=positions.copy()
            if variant=='energy90percent':
                for state in states.values():state['energy']*=.9
            elif variant=='charging_tb2':
                states['tb2']['mode']='CHARGING'
                planning['tb2']=(states['tb2']['charge_x'],states['tb2']['charge_y'])
            case={'snapshot':str(source),'observer':observer,'variant':variant,'durations_sec':{},'assignments':{}}
            for label,c in [('v45',old),('v47',new)]:
                started=time.monotonic()
                goals=c.assign_rally_poses(grid,info['resolution'],origin,planning,target,
                    battery_states=states,observer_robot=observer,current_positions=positions)
                case['durations_sec'][label]=time.monotonic()-started
                case['assignments'][label]={n:vars(p) for n,p in goals.items()}
            assert case['assignments']['v45']==case['assignments']['v47'],case
            output['cases'].append(case)
output['status']='PASS';output['equivalent_cases']=len(output['cases'])
Path('/tmp/p3b5_v47_bounds_component.json').write_text(json.dumps(output,indent=2)+'\n')
print('PASS identical assignments on',len(output['cases']),'conditional received/synthetic cases')

